import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] allSums(long[] a, int from, int to) {
        long[] sums = new long[1 << (to - from)];
        int size = 1;
        for (int i = from; i < to; i++) {
            for (int k = 0; k < size; k++) sums[size + k] = sums[k] + a[i];
            size *= 2;
        }
        return sums;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long g = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int half = (int) n / 2;
        long[] left = allSums(a, 0, half), right = allSums(a, half, (int) n);
        Arrays.sort(left);
        Arrays.sort(right);
        long best = Math.abs(g);
        int j = right.length - 1;
        for (long x : left) {
            while (j > 0 && x + right[j] > g) j--;
            for (int k = j; k <= j + 1; k++) {
                if (k < right.length) best = Math.min(best, Math.abs(x + right[k] - g));
            }
        }
        System.out.println(best);
    }
}
